public static async Task<string?> ReadFrameAsync(Stream stream, CancellationToken cancellationToken)
{
    byte[] prefix = new byte[4];
    int bytesRead = 0;
    while (bytesRead < 4)
    {
        int read = await stream.ReadAsync(prefix.AsMemory(bytesRead, 4 - bytesRead), cancellationToken);
        if (read == 0)
        {
            if (bytesRead == 0)
                return null;
            throw new EndOfStreamException();
        }
        bytesRead += read;
    }

    int length = (prefix[0] << 24) | (prefix[1] << 16) | (prefix[2] << 8) | prefix[3];

    if (length > 1024 * 1024)
        throw new InvalidDataException("Frame length exceeds 1 MiB limit.");

    if (length == 0)
        return string.Empty;

    byte[] payload = new byte[length];
    bytesRead = 0;
    while (bytesRead < length)
    {
        int read = await stream.ReadAsync(payload.AsMemory(bytesRead, length - bytesRead), cancellationToken);
        if (read == 0)
            throw new EndOfStreamException();
        bytesRead += read;
    }

    try
    {
        return Encoding.UTF8.GetString(payload);
    }
    catch (ArgumentException)
    {
        throw new InvalidDataException("Invalid UTF-8 sequence in frame payload.");
    }
}
